<script setup>
import {computed,nextTick,onBeforeUnmount,onMounted,ref,watch} from 'vue'
const props=defineProps({open:Boolean,locale:{type:String,default:'zh'}})
const emit=defineEmits(['close'])
const field=ref(null),query=ref(''),index=ref([]),loading=ref(false),includeProject=ref(false),error=ref(''),selected=ref(0)
let previousFocus=null
const results=computed(()=>{const terms=query.value.toLowerCase().trim().split(/\s+/).filter(Boolean);if(!terms.length)return[];return index.value.filter(p=>p.locale===props.locale&&(includeProject.value||p.audience!=='project')).map(p=>{const title=p.title.toLowerCase(),body=p.text.toLowerCase();if(!terms.every(t=>title.includes(t)||body.includes(t)))return null;const score=terms.reduce((s,t)=>s+(title===t?30:title.includes(t)?15:1),0);const pos=body.indexOf(terms[0]);return {...p,score,preview:p.text.slice(Math.max(0,pos-30),Math.max(0,pos-30)+115)}}).filter(Boolean).sort((a,b)=>b.score-a.score).slice(0,18)})
async function load(){if(index.value.length||loading.value)return;loading.value=true;try{const response=await fetch('/search-index.json');if(!response.ok)throw new Error();index.value=await response.json()}catch{error.value=props.locale==='zh'?'索引加载失败，请关闭后重试。':'Could not load the search index. Please try again.'}finally{loading.value=false}}
watch(()=>props.open,async open=>{if(open){previousFocus=document.activeElement;query.value='';selected.value=0;error.value='';load();await nextTick();field.value?.focus();document.body.classList.add('dialog-open')}else{document.body.classList.remove('dialog-open');previousFocus?.focus?.()}})
watch(query,()=>{selected.value=0})
function keydown(e){if(!props.open)return;if(e.key==='Escape'){e.preventDefault();emit('close')}if(e.key==='ArrowDown'){e.preventDefault();selected.value=Math.min(selected.value+1,results.value.length-1)}if(e.key==='ArrowUp'){e.preventDefault();selected.value=Math.max(0,selected.value-1)}if(e.key==='Enter'&&results.value[selected.value]){e.preventDefault();document.querySelector(`[data-search-result="${selected.value}"]`)?.click()}if(e.key==='Tab'){const elements=[...document.querySelectorAll('[data-search-dialog] button,[data-search-dialog] input,[data-search-dialog] a')];const a=elements[0],z=elements.at(-1);if(e.shiftKey&&document.activeElement===a){e.preventDefault();z?.focus()}else if(!e.shiftKey&&document.activeElement===z){e.preventDefault();a?.focus()}}}
onMounted(()=>document.addEventListener('keydown',keydown));onBeforeUnmount(()=>{document.removeEventListener('keydown',keydown);document.body.classList.remove('dialog-open')})
</script>
<template><Teleport to="body"><div v-if="open" class="search-overlay" @click.self="emit('close')"><section class="search-dialog" role="dialog" aria-modal="true" :aria-label="locale==='zh'?'搜索文档':'Search documentation'" data-search-dialog><div class="search-input-row"><span>⌕</span><input ref="field" v-model="query" type="search" :placeholder="locale==='zh'?'搜索操作步骤、数据库或错误…':'Search steps, databases or errors…'" :aria-label="locale==='zh'?'搜索关键词':'Search terms'"><button @click="emit('close')" aria-label="Close search">Esc</button></div><label class="search-scope"><input v-model="includeProject" type="checkbox">{{locale==='zh'?'同时搜索项目资料（架构、计划与验收）':'Include project resources'}}</label><div class="search-result-area"><p v-if="loading" class="search-hint">{{locale==='zh'?'正在加载文档索引…':'Loading documentation…'}}</p><p v-else-if="error" class="search-hint">{{error}}</p><p v-else-if="!query.trim()" class="search-hint">{{locale==='zh'?'例如：创建任务、PostgreSQL、数据校验、无法登录':'Try: quick start, PostgreSQL, recovery'}}</p><p v-else-if="!results.length" class="search-hint">{{locale==='zh'?'没有匹配结果，请尝试更短的关键词。':'No results. Try a shorter query.'}}</p><a v-for="(item,i) in results" :key="item.route" :data-search-result="i" :href="item.route" class="search-result" :class="{selected:i===selected}" @click="emit('close')" @mouseenter="selected=i"><small>{{item.group}}</small><strong>{{item.title}}</strong><span>{{item.preview}}…</span></a></div><div class="search-footer">↑ ↓ {{locale==='zh'?'切换':'Navigate'}} · Enter {{locale==='zh'?'打开':'Open'}} · Esc {{locale==='zh'?'关闭':'Close'}}<span>{{locale==='zh'?'本地文档索引，无外部搜索服务':'Static local index · no external search service'}}</span></div></section></div></Teleport></template>
